import{_ as t,o,c as i,a2 as s}from"./chunks/framework.Cs11k9ph.js";const g=JSON.parse('{"title":"Intent Launcher","description":"","frontmatter":{},"headers":[],"relativePath":"Android_init/README.md","filePath":"Android_init/README.md","lastUpdated":1789914293000}'),a={name:"Android_init/README.md"};function d(n,e,c,l,r,h){return o(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="intent-launcher" tabindex="-1">Intent Launcher <a class="header-anchor" href="#intent-launcher" aria-label="Permalink to &quot;Intent Launcher&quot;">​</a></h1><p>用 <code>intent://</code> URI 唤起 Android 原生应用的纯静态网页。</p><p>核心思路：<strong>不写死包名</strong>。生成的链接只描述「要做什么」（scheme / action / category / extras），由 Android 的 Intent 解析器去决定「哪个 App 来处理」——也就是系统自动识别。 需要定向到某个 App 时，才在高级参数里填 <code>package=</code>。</p><h2 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to &quot;文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>index.html</code></td><td>整个页面（界面、样式、逻辑都在里面）</td></tr><tr><td><code>intent-uri.js</code></td><td>intent:// 链接的构造与解析核心，UMD，浏览器和 Node 都能用</td></tr><tr><td><code>presets.js</code></td><td>预设列表：系统标准 action + 第三方 App 自定义 scheme</td></tr><tr><td><code>vendor/qrcode.js</code></td><td>第三方二维码库（qrcode-generator 2.0.4，MIT，见同目录 README）</td></tr><tr><td><code>.nojekyll</code></td><td>空文件，让 GitHub Pages 跳过 Jekyll 处理</td></tr><tr><td><code>build-single.cjs</code></td><td>可选：把整站打包成单个自包含的 <code>dist/index.html</code></td></tr><tr><td><code>test/</code></td><td>测试，见下方「验证」</td></tr></tbody></table><p>没有后端、没有依赖、没有构建步骤。四个文件放进任意静态空间就能跑。</p><h2 id="部署到-github-pages" tabindex="-1">部署到 GitHub Pages <a class="header-anchor" href="#部署到-github-pages" aria-label="Permalink to &quot;部署到 GitHub Pages&quot;">​</a></h2><p>把 <code>intent-launcher/</code> 里的东西放到仓库根目录（<code>index.html</code> 必须在根），然后 <strong>Settings → Pages → Source 选 &quot;Deploy from a branch&quot; → 分支选 <code>main</code>、目录选 <code>/ (root)</code></strong>， 保存后访问 <code>https://&lt;用户名&gt;.github.io/&lt;仓库名&gt;/</code>。不需要 Actions，不需要配构建。</p><p>几点实测确认过的：</p><ul><li>页面里所有引用都是<strong>相对路径</strong>，所以放在 <code>/仓库名/</code> 这种子路径下一切正常 （子路径和根路径的行为差异是新项目最容易踩的坑，我按子路径跑过一遍）。</li><li>二维码里的「页面链接」由 <code>location.href</code> 推导，会<strong>自动带上子路径</strong>， 所以扫码回到的是 <code>https://&lt;用户名&gt;.github.io/&lt;仓库名&gt;/#u=&lt;链接&gt;</code>，链接不丢。</li><li>GitHub Pages 是 HTTPS，<code>navigator.clipboard</code> 能直接用（局域网 <code>http://</code> 下不行， 页面里有 <code>execCommand</code> 兜底）。</li><li>部署到 Pages 之后，手机不用和电脑同一个 Wi-Fi 了，扫码即可用 —— 也可以直接把网址发给别人。</li></ul><p>想让二维码里的页面链接指向你自己的域名，就在 <code>index.html</code> 里改 <code>pageLinkFor()</code>。</p><h3 id="只想要一个文件" tabindex="-1">只想要一个文件 <a class="header-anchor" href="#只想要一个文件" aria-label="Permalink to &quot;只想要一个文件&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-single.cjs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 生成 dist/index.html，约 140KB，零外部请求</span></span></code></pre></div><p><code>dist/index.html</code> 把 CSS 和三个 JS 全部内联了，可以单独打开、单独发给别人、 或者丢到任何不能带同级资源的地方。它是<strong>生成物</strong>，改代码请改仓库根目录那几个文件 再重新生成 —— 根目录那套多文件版本才是测试覆盖的对象，也才是你在浏览器里看到的版本。</p><h2 id="本地预览" tabindex="-1">本地预览 <a class="header-anchor" href="#本地预览" aria-label="Permalink to &quot;本地预览&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> intent-launcher</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http.server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span></span></code></pre></div><p>打开 <code>http://127.0.0.1:8000/</code>。要在手机上试而在本地起服务，就用 <code>python -m http.server 8000 --bind 0.0.0.0</code>，然后在<strong>同一 Wi-Fi 下</strong>用手机 Chrome 打开 <code>http://&lt;电脑的局域网IP&gt;:8000/</code>（Windows 查 IP：<code>ipconfig</code>）。 直接双击 <code>index.html</code> 用 <code>file://</code> 打开也能用，只是少了 HTTPS 带来的剪贴板便利。</p><blockquote><p><code>intent://</code> 只有 Android 系统能解析。桌面浏览器点「唤起应用」不会有任何反应 —— 这不是 bug，页面顶部也会提示。桌面上可以正常构造、复制、生成二维码。</p></blockquote><h2 id="页面里有什么" tabindex="-1">页面里有什么 <a class="header-anchor" href="#页面里有什么" aria-label="Permalink to &quot;页面里有什么&quot;">​</a></h2><ul><li><strong>快速唤起</strong>：粘贴任意链接，自动判断类型并给出实际会被唤起的链接。 自定义 scheme（<code>weixin://…</code>）默认会包一层 <code>intent://</code>，走系统解析器并带上 <code>BROWSABLE</code>； 也可以关掉这个开关，直接投递原始链接。</li><li><strong>可视化构建</strong>：目标 URI（可直接粘贴，也可按 scheme/host/path/query 拆开填）＋ action / category / type / package / component / launchFlags / extras / <code>browser_fallback_url</code>，实时生成链接，并单独显示 App 最终收到的 data。</li><li><strong>常见应用</strong>：37 个预设，分「系统 Intent」（标准 action，任何设备都能应答）和 「第三方 App」（自定义 scheme，属于约定值）两组，可一键唤起或载入构建器继续改。</li><li><strong>语法与限制</strong>：URI 结构、参数表、浏览器的唤起限制清单、排错速查。</li><li><strong>二维码</strong>：默认编码「本页 + <code>#u=&lt;链接&gt;</code>」，手机扫码后打开的就是带着这条链接的页面， 再点一下按钮（Chrome 要求唤起必须来自真实用户手势）；也可以切换成直接编码链接本身。</li><li>最近唤起的记录存在 localStorage，不上传任何东西。</li></ul><h2 id="链接语法-要点" tabindex="-1">链接语法（要点） <a class="header-anchor" href="#链接语法-要点" aria-label="Permalink to &quot;链接语法（要点）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>intent://&lt;host&gt;&lt;path&gt;?&lt;query&gt;#Intent;scheme=…;action=…;category=…;S.key=value;end</span></span></code></pre></div><p>两个最容易写错的地方：</p><ol><li><strong><code>intent://host</code> 和 <code>intent:opaque</code> 不是一回事。</strong> Android 的还原规则是 <code>data = scheme + &quot;:&quot; + 去掉 intent: 之后的原文</code>，所以 <code>intent://dl/nav</code> 配 <code>scheme=weixin</code> 得到 <code>weixin://dl/nav</code>，而 <code>intent:10086</code> 配 <code>scheme=smsto</code> 得到 <code>smsto:10086</code>（<strong>没有</strong> <code>//</code>）。 <code>tel:</code>、<code>smsto:</code>、<code>mailto:</code>、<code>geo:</code> 这类 opaque URI 必须写成没有斜杠的形式。</li><li><strong><code>B.</code> 是 boolean，<code>b.</code> 是 byte。</strong> 大小写和不少博客写的相反，以 AOSP <code>Intent.parseUri</code> 源码为准。 完整前缀：<code>S.</code> 字符串、<code>i.</code>/<code>l.</code>/<code>s.</code>/<code>b.</code> 整型、<code>B.</code> 布尔、<code>f.</code>/<code>d.</code> 浮点、<code>c.</code> 字符。</li></ol><p>另外：参数值里的 <code>;</code> 必须转义（它是分隔符），<code>#Intent;…;end</code> 的 <code>end</code> 是结束标记； <code>component=</code> 指定的显式 Intent 会被 Chrome 用 <code>setComponent(null)</code> 清掉，从网页基本无效。</p><h2 id="浏览器什么时候会拒绝唤起" tabindex="-1">浏览器什么时候会拒绝唤起 <a class="header-anchor" href="#浏览器什么时候会拒绝唤起" aria-label="Permalink to &quot;浏览器什么时候会拒绝唤起&quot;">​</a></h2><p>摘自分发到 Chromium <code>components/external_intents</code> 与 Chrome 的 <a href="https://developer.chrome.com/docs/android/intents" target="_blank" rel="noreferrer">Android Intents with Chrome</a> 文档：</p><ul><li>不是真实用户手势触发的（定时器、自动跳转、加载即触发）会被拦；</li><li>指定的 Intent 解析不到任何应用 → 静默无反应，可用 <code>S.browser_fallback_url</code> 兜底；</li><li>显式 Intent（带 <code>component</code>）、或缺少 <code>BROWSABLE</code> category 的会被拦 （Chrome 自己会给 Intent 补上 <code>BROWSABLE</code>）；</li><li>从重定向链路上来的 Intent URI 不会被唤起；</li><li>浏览器自己能处理的 scheme（http/https）不会被抢走，除非 App 声明了<strong>已验证</strong>的 App Link（<code>autoVerify</code> + <code>/.well-known/assetlinks.json</code>）；</li><li>同一个用户手势里重复尝试唤起会被当成指纹探测而拦截；</li><li><code>file:</code> / <code>content:</code> 等属于受限 scheme。</li></ul><p>App 内置浏览器（微信 / QQ / 微博等）普遍直接屏蔽唤起，请用 Chrome 测试。</p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/uri.test.cjs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 96 项：链接语法</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/qr.check.cjs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 生成二维码图</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/qr.rgba.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 导出像素</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/qr.decode-jsqr.cjs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 用 jsQR 解码回读</span></span></code></pre></div><p><code>test/uri.test.cjs</code> 不是自说自话的断言：<code>test/aosp-oracle.js</code> 是 <strong>AOSP <code>Intent.parseUri</code> 的移植</strong>，每个生成的链接都用它解析回来，断言「Android 实际会 看到什么」——包括 data URI 的还原方式、extras 各自落成什么 Bundle 类型、以及 <code>;</code> <code>=</code> <code>#</code> <code>中文</code> 这些会撞上语法的值。其中一项直接对照 Chrome 文档里的 ZXing 示例， 要求<strong>逐字节一致</strong>。</p><p><code>node test/uri.test.cjs</code> 的输出里有一条值得单独说的是： <code>B.</code>/<code>b.</code> 的映射是照着 AOSP 源码写的，测试用 oracle 的 <code>parseNum</code>/布尔分支独立验证了一遍。</p><p>二维码用两个解码器交叉验证（OpenCV 的 <code>QRCodeDetector</code> 会拒掉一些合法的高版本码， 所以以 jsQR 的结果为准）。<code>vendor/qrcode.js</code> 默认的字节编码器会把每个字符截成 8 位， 页面里已经换成它自带的 UTF-8 编码器，否则含中文的链接会生成扫不出来的码。</p><h3 id="验证到什么程度" tabindex="-1">验证到什么程度 <a class="header-anchor" href="#验证到什么程度" aria-label="Permalink to &quot;验证到什么程度&quot;">​</a></h3><ul><li>✅ intent:// 语法：与 AOSP <code>Intent.parseUri</code> 的移植实现逐字段对照，含边界与错误输入。</li><li>✅ 页面交互：真实浏览器里逐个操作过（构建器、extras 校验、预设、二维码弹层、 <code>#u=</code> 参数恢复、开关行为），并在 412×915 的手机视口下确认过布局。</li><li>✅ 二维码：页面 canvas 里实际画出来的图能被独立解码器读回原串。</li><li>⚠️ <strong>没有在真实 Android 设备 / 模拟器上跑过。</strong> 本机没有连接设备，也没有下载系统镜像， 所以「Chrome 点了之后到底跳不跳」这一步是按 Chromium 与 Chrome 的文档写的， 没有端到端实测。真机第一次用时建议先点「系统设置」这个预设 —— 它不依赖任何第三方 App， 能验证页面本身是通的。</li></ul><h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>生成的链接就是普通字符串，可以直接放进任意网页的 <code>&lt;a href&gt;</code>、二维码、或 <code>adb shell am start</code> 里：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> am</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> android.intent.action.VIEW</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;intent://#Intent;scheme=weixin;action=android.intent.action.VIEW;category=android.intent.category.BROWSABLE;end&quot;</span></span></code></pre></div>`,39)])])}const k=t(a,[["render",d]]);export{g as __pageData,k as default};
